"""Generate a tracked index for the ignored experiment-run archive."""

from __future__ import annotations

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def build_index(runs: Path, link_root: str = "runs") -> str:
    children = sorted(runs.iterdir(), key=lambda path: (not path.is_dir(), path.name.casefold()))
    lines = [
        "# Experiment runs",
        "",
        "<!-- Generated by generate_index.py; do not edit. -->",
        "",
        f"Archive entries: {len(children)}.",
        "",
        "| Name | Kind | Link |",
        "| --- | --- | --- |",
    ]
    for child in children:
        kind = "directory" if child.is_dir() else "file"
        relative = f"{link_root}/{child.name}"
        lines.append(f"| `{child.name}` | {kind} | [{relative}](<{relative}>) |")
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--runs", type=Path, default=ROOT / "runs")
    parser.add_argument("--output", type=Path, default=ROOT / "index.md")
    args = parser.parse_args()
    args.runs.mkdir(parents=True, exist_ok=True)
    args.output.write_text(build_index(args.runs), encoding="utf-8")
    print(args.output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
